"""Generate standalone objective/budget result viewer from frozen receipts."""
import json
from pathlib import Path

def build():
    payload={k:json.load(open(f)) for k,f in [('objective','objective_results.json'),('budget','budget_frontier_results.json'),('cert','objective_cert_results.json')]}
    return TEMPLATE.replace('__DATA__',json.dumps(payload,separators=(',',':')).replace('</','<\\/'))
TEMPLATE='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Adaptive Resolution Lab · 목적함수 실험</title><style>
*{box-sizing:border-box}body{margin:0;background:#f5f6f7;color:#182433;font:15px/1.55 system-ui,sans-serif}main{max-width:1100px;padding:24px;margin:auto}h1{font-size:27px;margin:6px 0}h2{font-size:19px}p{margin:8px 0}.sub{color:#536578}.panel{background:white;padding:20px;border:1px solid #d9e1e8;border-radius:12px;margin:16px 0}.controls{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}label{display:grid;gap:5px;font-weight:600}select{width:100%;padding:9px;border:1px solid #a8b7c4;border-radius:6px;background:white;font:inherit;color:inherit}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}td,th{padding:9px 8px;text-align:right;border-bottom:1px solid #e7ebee;white-space:nowrap}th:first-child,td:first-child{text-align:left}th{color:#526578;font-size:13px}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.metric{padding:12px;border:1px solid #d9e1e8;border-radius:7px}.number{font-size:24px;font-weight:700;font-variant-numeric:tabular-nums}.bars{display:grid;gap:9px}.barrow{display:grid;grid-template-columns:45px 1fr 80px;gap:8px;align-items:center}.track{height:12px;background:#edf0f2;border-radius:3px;overflow:hidden}.bar{height:100%;background:#346c9c}.note{color:#536578;font-size:13px}svg{width:100%;height:auto;display:block}button{font:inherit} @media(max-width:600px){main{padding:13px}.panel{padding:12px}.controls,.metrics{grid-template-columns:1fr}.number{font-size:21px}h1{font-size:23px}}
</style><main><p class="sub">R&E 2027 / 합성 모형 · R2 실험 뷰어</p><h1>관측 예산과 최적화 목적</h1><p>실제 관측 자료나 도로 제어 결과가 아닌, 사전 계산한 유리수 최적화 실험을 탐색합니다. 새로운 조건은 별도 Python CLI로 계산합니다.</p><section class="panel controls"><label>관측·서비스 환경<select id="law"><option value="ideal">이상적</option><option value="broad" selected>누락 25% · 서비스 변동</option></select></label><label>초기 대기 공간 및 차량 구성<select id="cls"><option value="0">(2,2) · 직진 3 / 좌회전 1</option><option value="1">(2,0) · 직진 2 / 좌회전 2</option><option value="2">(0,2) · 직진 2 / 좌회전 2</option><option value="3">(1,1) · 직진 2 / 좌회전 2</option></select></label><label>목적함수<select id="weight"></select></label></section><section class="panel"><h2>동일 최대 예산 4에서 정책 비교</h2><div id="metrics" class="metrics"></div><div class="scroll"><table id="policies"></table></div><p class="note">최대 이동류 잔류량은 개인별 대기시간·형평성 보장이 아닙니다. 모든 수치는 기대값이며 최대 예산은 경로별 제약입니다.</p></section><section class="panel"><h2>계산 깊이와 최적성 인증</h2><div class="scroll"><table id="cert"></table></div><p class="note">하한과 실행 가능 정책의 상한이 일치할 때만 정확 최적성을 인증합니다. 실제 최적해와 동률이라도 하한이 느슨하면 미인증일 수 있습니다.</p></section><section class="panel"><h2>관측 예산에 따른 최적 비용</h2><label>가격 제외 목적<select id="budgetobj"><option value="0">총잔류량</option><option value="1" selected>총잔류량 + 4 × 단계별 최대 잔류량</option></select></label><svg id="curve" viewBox="0 0 600 200" role="img" aria-label="관측 예산별 비용 곡선"></svg><div class="scroll"><table id="budget"></table></div><p class="note">예산 상한이 같아도 실제 지출은 다를 수 있습니다. 관측 가격을 0으로 놓아 예산 자체의 효과를 분리했습니다.</p></section></main><script>
const D=__DATA__;const $=x=>document.getElementById(x);const labels=['총잔류량 + 관측비용','총잔류량 + 최대잔류량','총잔류량 + 4×최대잔류량','총잔류량 + 2×최종잔류량','직진 우선 가중치 4','좌회전 우선 가중치 4','총잔류량 (관측 가격 0)','총잔류량 + 관측 가격 4배'];const names={free:'기본',head:'선두 우선',full:'전체 우선',depth2:'두 단계',exact:'정확 적응'};const qn=['straight','left','stage_max','terminal','credits'];const val=x=>{let [n,d]=String(x).split('/').map(Number);return d?n/d:n};const fmt=x=>val(x).toFixed(4);const row=x=>'<tr>'+x.map(t=>'<td>'+t+'</td>').join('')+'</tr>';const header=x=>'<tr>'+x.map(t=>'<th>'+t+'</th>').join('')+'</tr>';$('weight').innerHTML=labels.map((s,i)=>`<option value="${i}" ${i===2?'selected':''}>${s}</option>`).join('');function render(){let law=$('law').value,i=+$('cls').value,j=+$('weight').value,g=D.objective.filter(x=>x.law===law)[i],r=g.rows[j],ex=r.policies.exact,ca=D.cert.rows.find(x=>x.law===law&&x.q.join()==g.q.join()&&x.weights.join()==r.weights.join());let fixed=val(r.gain_vs_fixed),cost=val(ex.objective);$('metrics').innerHTML=[['정확 적응 비용',fmt(ex.objective)],['강한 기준선 대비 개선',((fixed/(cost+fixed))*100).toFixed(3)+'%'],['두 단계 초과 비용',(val(r.policies.depth2.objective)-cost).toFixed(5)]].map(([k,v])=>`<div class="metric"><div class="note">${k}</div><div class="number">${v}</div></div>`).join('');$('policies').innerHTML=header(['정책','직진','좌회전','단계 최대','최종','크레디트','최대 사용','목적 비용'])+Object.entries(r.policies).map(([n,p])=>row([names[n],...qn.map(k=>fmt(p.vector[k])),p.worst_credits,fmt(p.objective)])).join('');$('cert').innerHTML=header(['설정','탐색 깊이','정책 깊이','하한','상한','격차','판정'])+ca.cases.map((x,i)=>row([['상한 2 / 정확','상한 4 / 정확','상한 4 / 허용 1/64'][i],x.explored_depth,x.selected_depth,fmt(x.lower),fmt(x.upper),fmt(x.gap),x.exact?'정확 인증':x.certified?'허용오차 인증':'미인증'])).join('');let obj=+$('budgetobj').value,curve=D.budget.find(x=>x.law===law&&x.q.join()==g.q.join()&&x.weights[2]==(obj?4:0)),v=curve.rows.map(x=>val(x.policy.adaptive.objective)),max=Math.max(...v),min=Math.min(...v),span=Math.max(.001,max-min),px=k=>48+k*100/8*5,py=x=>35+(max-x)/span*110;let points=curve.rows.map((x,k)=>[48+x.budget*65,py(v[k])]);$('curve').innerHTML=`<path d="M48 20V155H568" fill="none" stroke="#91a3b0"/><path d="${points.map(([x,y],i)=>(i?'L':'M')+x+' '+y).join(' ')}" fill="none" stroke="#346c9c" stroke-width="3"/>`+points.map(([x,y],k)=>`<circle cx="${x}" cy="${y}" r="4" fill="#346c9c"/><text x="${x}" y="176" text-anchor="middle" font-size="11">${curve.rows[k].budget}</text>`).join('')+`<text x="48" y="15" font-size="12">${max.toFixed(4)} → ${min.toFixed(4)}</text>`;$('budget').innerHTML=header(['예산','최적 비용','최선 고정 대비 차이','기대 크레디트','경로 최대'])+curve.rows.map(x=>row([x.budget,fmt(x.policy.adaptive.objective),fmt(x.gain_vs_fixed),fmt(x.policy.adaptive.vector.credits),x.policy.adaptive.worst_credits])).join('');}['law','cls','weight','budgetobj'].forEach(n=>$(n).addEventListener('change',render));render();</script>'''
if __name__=='__main__':Path('objective_demo.html').write_text(build(),encoding='utf-8')
